# What leaves libav.so: FFmpeg's public interface, by its public prefixes.
# FFmpeg's own version scripts (lib*/lib*.v) also export avpriv_*, the
# names one FFmpeg library calls in another; here the three are one
# library, so avpriv_* stays local with ff_*, and no program can come to
# depend on an internal name an FFmpeg upgrade may change.
{
  global:
    av_*; avcodec_*; avformat_*; avio_*; avutil_*; avsubtitle_free;
  local: *;
};
